pre_manifest_qa.command:
$ErrorActionPreference='Stop'
$packageRoot=(Resolve-Path task-packages/PKG-A-SKILLS).Path
$repoRoot=(Get-Location).Path
$issues=@()
$pending=@()
$projection=@()
$linkCount=0
foreach($item in Get-ChildItem -LiteralPath $packageRoot -Recurse) {
  $relative=[IO.Path]::GetRelativePath($packageRoot,$item.FullName).Replace('\','/')
  if($relative -notmatch '^[A-Za-z0-9_./-]+$') { $issues+="Non-ASCII path: $relative" }
  if($item.PSIsContainer) {
    if(@(Get-ChildItem -LiteralPath $item.FullName -Force).Count -eq 0) { $issues+="Empty directory: $relative" }
    continue
  }
  $raw=[IO.File]::ReadAllText($item.FullName)
  if($raw -match '(?m)[ \t]+\r?$') { $issues+="Trailing whitespace: $relative" }
  if(-not $raw.EndsWith("`n")) { $issues+="Missing final newline: $relative" }
  if($item.Extension -ne '.md') { continue }
  foreach($match in [regex]::Matches($raw,'\[[^\]]+\]\(([^)]+)\)')) {
    $target=$match.Groups[1].Value.Split('#')[0]
    if(-not $target -or $target -match '^https?://') {continue}
    $linkCount++
    $resolved=[IO.Path]::GetFullPath((Join-Path $item.DirectoryName $target))
    if(Test-Path -LiteralPath $resolved) {continue}
    if($relative -eq 'payload/skill/README.md') {
      $installed=[IO.Path]::GetFullPath((Join-Path "$repoRoot/skill" $target))
      if(Test-Path -LiteralPath $installed) { $projection+=$target; continue }
    }
    if($resolved -in @("$packageRoot\MANIFEST.json","$packageRoot\evidence\validation-commands.json")) {
      $pending+=$relative+': '+$target; continue
    }
    $issues+="Broken link: $relative -> $target"
  }
}
$snapshot=Get-Content -Raw "$packageRoot/evidence/source-snapshot.json" | ConvertFrom-Json
$changed=@()
$unchanged=@()
foreach($row in $snapshot.files) {
  if((Test-Path -LiteralPath $row.path) -and (Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -eq $row.sha256) { $unchanged+=$row.path } else { $changed+=$row.path }
}
[pscustomobject]@{issues=$issues;markdown_links=$linkCount;installed_target_dependency_links=$projection;pending_generated_links=$pending;unchanged_snapshot_count=$unchanged.Count;changed_snapshot_paths=$changed;active_workflow_unchanged=(@($changed | Where-Object {$_ -eq 'skill/README.md' -or $_ -like 'skill/soundsight-engineering-workflow/*'}).Count -eq 0)} | ConvertTo-Json -Depth 5
if($issues.Count -gt 0) {exit 1}

